4630|# Health of one ENDPOINT (provider_fingerprint - never the alias) from the ledgers of all
4631|# tasks. Entries recorded before 0.3.0 count as the built-in openai endpoint; entries with
4632|# an unresolved identity (empty fingerprint) are ignored. A failure's class comes from its
4633|# provider_failure, else (older entries) from its bridge_outcome. Newest wins: a later
4634|# successful run clears an earlier auth or quota failure ("later" by completion: finished_at,
4635|# else when + wall_seconds; ties by n). $UtcNow: the consult clock
4636|# (Get-ConsultClock -Peek), so a test can freeze time.
4637|#   Auth         the newest of {success, auth failure} is an auth failure <= 24 h old
4638|#   Quota        the newest of {success, quota failure} is a quota failure that still
4639|#                blocks: its RetryAfter lies in the future, or it has no RetryAfter and its
4640|#                limit was hit less than 60 minutes ago (wave 24, T3: Hit + 60 min lies ahead
4641|#                - "out (limit hit <t>, reset unknown; retry after <t + 60 min>)"); a
4642|#                RetryAfter in the past clears it
4643|#   QuotaKnown   [bool] Quota is set and names its reset time (RetryAfter)
4644|#   LastLimit    the newest quota failure <= 24 h old, else (wave 24, T2) the Quota record
4645|#                that still blocks (a reset days ahead): an endpoint that is out never shows
4646|#                no failure at all
4647|#   LastFailure  the newest failure of any class <= 24 h old, else the Quota record that
4648|#                still blocks (informational)
4649|#   RecentUsable the newest usable reply <= 60 min old (wave 18: an engine's sign-in is then
4650|#                evidenced without a network check - Get-EngineCredential)
4651|# Each record is $null or { Class; Code; Message; When; AgeMinutes (a `when` in the future
4652|# counts as now: 0); RetryAfter (DateTimeOffset or $null: provider_failure.retry_after, else
4653|# Get-RetryAfter -ReferenceOffset on the recorded message with the failure's `when` as
4654|# reference); RetryAfterIso ('' when none); RetryAfterBasis ('ledger' | 'message (reference
4655|# offset)' | ''); Hit (wave 24: DateTimeOffset - when the failure happened: provider_failure.
4656|# when, else the entry's `when`; a time in the future counts as now); HitIso; Until
4657|# (RetryAfter, else Hit + 60 min) }. A usable reply is Test-UsableOutcome (a reply after a
4658|# timeout continuation counts).
4659|function Get-EndpointHealth {
4660|    param([object[]]$Consults, [string]$Fingerprint, [datetime]$UtcNow = [datetime]::UtcNow)
4661|    $h = [pscustomobject]@{ Auth = $null; Quota = $null; QuotaKnown = $false; LastLimit = $null; LastFailure = $null; RecentUsable = $null }
4662|    if (-not $Fingerprint) { return $h }
4663|    $nowOffset = New-Object DateTimeOffset ([datetime]::SpecifyKind($UtcNow, [DateTimeKind]::Utc))
4664|    $records = New-Object System.Collections.Generic.List[object]
4665|    foreach ($c in @($Consults | Where-Object { $null -ne $_ })) {
4666|        $rev = Get-PropertyValue $c 'reviewer' $null
4667|        $fp = if ($null -eq $rev) { $script:BuiltinOpenAiFingerprint } else { [string](Get-PropertyValue $rev 'provider_fingerprint' '') }
4668|        if (-not $fp -or $fp -ne $Fingerprint) { continue }
4669|        $outcome = [string](Get-PropertyValue $c 'bridge_outcome' '')
4670|        if (-not $outcome) { continue }
4671|        $at = ConvertTo-WhenOffset (Get-PropertyValue $c 'when' '')
4672|        if ($null -eq $at) { continue }
4673|        # A failure stamped in the future (clock skew, a mislabelled zone) counts as now:
4674|        # its age is clamped to 0, it is never skipped (F15-4).
4675|        $age = [Math]::Max(0, ($UtcNow - $at.UtcDateTime).TotalMinutes)
4676|        # "Newest" is by COMPLETION (D9, F03-3): a panel's members start together and finish in
4677|        # any order, so a member that started later may have succeeded before an earlier one hit
4678|        # its usage limit. finished_at (0.4.x wave 21), else when + wall_seconds (older entries),
4679|        # else when; ties by n (F02-5).
4680|        $order = ConvertTo-WhenOffset (Get-PropertyValue $c 'finished_at' '')
4681|        if ($null -eq $order) {
4682|            $order = $at
4683|            $ws = 0.0
4684|            if ([double]::TryParse([string](Get-PropertyValue $c 'wall_seconds' ''), [System.Globalization.NumberStyles]::Float, $script:Invariant, [ref]$ws) -and $ws -gt 0) { $order = $at.AddSeconds($ws) }
4685|        }
4686|        $entryN = 0
4687|        [void][int]::TryParse([string](Get-PropertyValue $c 'n' ''), [ref]$entryN)
4688|        $rec = [pscustomobject]@{ At = $at; Order = $order; N = $entryN; Ok = (Test-UsableOutcome $outcome); Class = ''; Code = ''; Message = ''; When = $at.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); AgeMinutes = [int][Math]::Max(0, [Math]::Floor($age)); Age = $age; RetryAfter = $null; RetryAfterIso = ''; RetryAfterBasis = ''; Hit = $at; HitIso = ''; Until = $at.AddMinutes(60) }
4689|        if (-not $rec.Ok) {
4690|            $reference = $at
4691|            $pf = Get-PropertyValue $c 'provider_failure' $null
4692|            if ($null -ne $pf) {
4693|                $rec.Class = [string](Get-PropertyValue $pf 'class' 'unknown')
4694|                # An entry recorded as auth whose message says usage limit / quota / rate limit
4695|                # counts as quota (Get-ProviderFailureClass's rule, applied when the ledger is
4696|                # READ): a 401/403 with a usage-limit text recorded before that rule existed
4697|                # (Kimi Code's 5-hour limit) stops refusing the endpoint for 24 h as an auth
4698|                # failure - without anyone editing the ledger.
4699|                if ($rec.Class -eq 'auth' -and ([string](Get-PropertyValue $pf 'message' '')) -match $script:QuotaTextPattern) { $rec.Class = 'quota' }
4700|                $rec.Code = [string](Get-PropertyValue $pf 'code' '')
4701|                $rec.Message = [string](Get-PropertyValue $pf 'message' '')
4702|                $pfWhen = ConvertTo-WhenOffset (Get-PropertyValue $pf 'when' '')
4703|                if ($null -ne $pfWhen) { $reference = $pfWhen }
4704|                $recorded = Get-PropertyValue $pf 'retry_after' $null
4705|                if ($null -ne $recorded -and "$recorded") { $rec.RetryAfter = ConvertTo-WhenOffset $recorded }
4706|            } else {
4707|                # older entry: classify its bridge_outcome, lifting an SSE/JSON error payload
4708|                $parsedOutcome = ConvertFrom-ProviderErrorText -Text $outcome
4709|                $rec.Class = Get-ProviderFailureClass "$($parsedOutcome.Code) $outcome"
4710|                $rec.Code = $parsedOutcome.Code
4711|                $rec.Message = $parsedOutcome.Message
4712|            }
4713|            # an entry recorded without retry_after: read the reset time from its message now
4714|            if ($null -ne $rec.RetryAfter) { $rec.RetryAfterBasis = 'ledger' }
4715|            else {
4716|                $rec.RetryAfter = Get-RetryAfter -Message $rec.Message -Reference $reference -ReferenceOffset
4717|                if ($null -ne $rec.RetryAfter) { $rec.RetryAfterBasis = 'message (reference offset)' }
4718|            }
4719|            # (wave 24) when the failure happened - a time in the future counts as now (F15-4) -
4720|            # and, without a reset time, the 60 minutes it stays out
4721|            $hit = $reference
4722|            if ($hit.UtcDateTime -gt $UtcNow) { $hit = $nowOffset.ToOffset($hit.Offset) }
4723|            $rec.Hit = $hit
4724|            $rec.HitIso = Format-OffsetIso $hit
4725|            $rec.Until = $hit.AddMinutes(60)
4726|            if ($null -ne $rec.RetryAfter) {
4727|                $rec.RetryAfterIso = Format-OffsetIso $rec.RetryAfter
4728|                $rec.Until = $rec.RetryAfter
4729|            }
4730|            if ($rec.Message.Length -gt 100) { $rec.Message = $rec.Message.Substring(0, 100) }
4731|        }
4732|        $records.Add($rec)
4733|    }
4734|    $sorted = @($records | Sort-Object -Property @{ Expression = { $_.Order }; Descending = $true }, @{ Expression = { $_.N }; Descending = $true })
4735|    $auth = @($sorted | Where-Object { $_.Ok -or $_.Class -eq 'auth' }) | Select-Object -First 1
4736|    if ($auth -and -not $auth.Ok -and $auth.AgeMinutes -le 24 * 60) { $h.Auth = $auth }
4737|    $quota = @($sorted | Where-Object { $_.Ok -or $_.Class -eq 'quota' }) | Select-Object -First 1
4738|    if ($quota -and -not $quota.Ok) {
4739|        if ($null -ne $quota.RetryAfter) {
4740|            if ($quota.RetryAfter.UtcDateTime -gt $UtcNow) { $h.Quota = $quota }
4741|        } elseif ($quota.Until.UtcDateTime -gt $UtcNow) {
4742|            $h.Quota = $quota
4743|        }
4744|    }
4745|    $h.QuotaKnown = [bool]($h.Quota -and $null -ne $h.Quota.RetryAfter)
4746|    $h.LastLimit = @($sorted | Where-Object { -not $_.Ok -and $_.Class -eq 'quota' -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
4747|    $h.LastFailure = @($sorted | Where-Object { -not $_.Ok -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
4748|    if (-not $h.LastLimit -and $h.Quota) { $h.LastLimit = $h.Quota }
4749|    if (-not $h.LastFailure -and $h.Quota) { $h.LastFailure = $h.Quota }
