5427|# Every roster entry's availability (D15): Select-PanelMembers -All [-NoNetwork] - the roster
5428|# walk's verdict for each entry, in roster order - plus the endpoint groups over ALL entries
5429|# (Get-EndpointGroups; D16: an outage recorded on an endpoint - auth, a usage limit - marks every
5430|# entry of its group). { Records (object[] in roster order of { Position; Provider; Model;
5431|# Engine; Lineage ('<provider> :: <model>'); Group; State available|out|not checked; Kind
5432|# (Get-PreflightVerdict's, or refused); Reason (the roster walk's reason); Short (the one-line
5433|# view's phrase, local time - Format-AvailabilityLine); Hit; Until }); Groups (Get-EndpointGroups);
5434|# Total; Available; Out; NotChecked; Selected (the first available record - the entry the
5435|# single-reviewer walk selects - or $null) }.
5436|function Get-RosterAvailability {
5437|    param($Roster, $Config, [object[]]$Consults, [string]$Launcher, [hashtable]$LoginCache = $null, [datetime]$UtcNow = [datetime]::UtcNow, [string]$OpenAiBaseUrl = '', [hashtable]$EngineLaunchers = $null, [switch]$NoNetwork)
5438|    $sel = Select-PanelMembers -Roster $Roster -Config $Config -Consults $Consults -Launcher $Launcher -LoginCache $LoginCache -UtcNow $UtcNow -OpenAiBaseUrl $OpenAiBaseUrl -All -EngineLaunchers $EngineLaunchers -NoNetwork:$NoNetwork
5439|    $members = @($sel.Members | Where-Object { $_ })
5440|    $eg = Get-EndpointGroups -Members $members
5441|    $records = New-Object System.Collections.Generic.List[object]
5442|    foreach ($m in $members) {
5443|        $pos = [int]$m.Entry.Position
5444|        $records.Add((ConvertTo-AvailabilityRecord -Position $pos -Provider ([string]$m.Entry.Provider) -Model ([string]$m.Identity.Model) -Engine ([string]$m.Entry.Engine) -Group ([int]$eg.GroupOf[$pos]) -Verdict $m.Verdict -Block ([string]$m.Block) -UtcNow $UtcNow))
5445|    }
5446|    # D16: an outage recorded on the endpoint marks the whole group (an entry of it that was not
5447|    # judged out by itself - e.g. an unresolved one - is out with the same reason)
5448|    foreach ($rec in @($records | Where-Object { $_.State -eq 'out' -and @('auth', 'quota', 'quota-unknown-reset') -contains $_.Kind })) {
5449|        foreach ($o in @($records | Where-Object { $_.Group -eq $rec.Group -and $_.State -ne 'out' })) {
5450|            $o.State = 'out'; $o.Kind = $rec.Kind; $o.Reason = $rec.Reason; $o.Hit = $rec.Hit; $o.Until = $rec.Until; $o.Short = $rec.Short
5451|        }
5452|    }
5453|    $all = [object[]]$records.ToArray()
5454|    return [pscustomobject]@{
5455|        Records    = $all
5456|        Groups     = $eg
5457|        Total      = $all.Count
5458|        Available  = @($all | Where-Object { $_.State -eq 'available' }).Count
5459|        Out        = @($all | Where-Object { $_.State -eq 'out' }).Count
5460|        NotChecked = @($all | Where-Object { $_.State -eq 'not checked' }).Count
5461|        Selected   = (@($all | Where-Object { $_.State -eq 'available' }) | Select-Object -First 1)
5462|    }
5463|}
5464|
5465|# The one-line availability view (D17; the SessionStart hook, codex-providers.ps1 -Short): what is
5466|# OUT and what was NOT CHECKED, per roster entry, then the count -
5467|#   codex-consult: out - openai :: gpt-6-astra (until Sun 20:35, in 2d 10h), gemini :: * (until
5468|#   Sun 21:30, in 2d 11h); 9 of 11 reviewers available
5469|#   codex-consult: all 11 reviewers available
5470|# The entries of one endpoint group collapse to '<label> :: *' (labels of a merged group joined by
5471|# '+') when there are at least two and all share the state and the phrase; otherwise one clause
5472|# per entry. Nothing is cut. The count names the not-checked entries ("7 of 11 reviewers
5473|# available, 2 out, 2 not checked") whenever there are any (then the three counts do not add up
5474|# from the clauses alone). $Noun: 'reviewers' (a roster) or 'providers' (none).
5475|function Format-AvailabilityLine {
5476|    param($Availability, [string]$Noun = 'reviewers', [string]$Prefix = 'codex-consult: ', [string]$Suffix = '')
5477|    $recs = @($Availability.Records | Where-Object { $_ })
5478|    $n = $recs.Count
5479|    $noun = $(if ($n -eq 1) { $Noun -replace 's$', '' } else { $Noun })
5480|    if ($n -eq 0) { return "${Prefix}no $Noun to check$Suffix" }
5481|    $a = @($recs | Where-Object { $_.State -eq 'available' }).Count
5482|    $o = @($recs | Where-Object { $_.State -eq 'out' }).Count
5483|    $c = @($recs | Where-Object { $_.State -eq 'not checked' }).Count
5484|    if ($o -eq 0 -and $c -eq 0) { return "${Prefix}all $n $noun available$Suffix" }
5485|    $parts = New-Object System.Collections.Generic.List[string]
5486|    foreach ($state in @('out', 'not checked')) {
5487|        $these = @($recs | Where-Object { $_.State -eq $state })
5488|        if ($these.Count -eq 0) { continue }
5489|        $clauses = New-Object System.Collections.Generic.List[string]
5490|        $done = @{}
5491|        foreach ($r in $these) {
5492|            if ($done.ContainsKey($r.Group)) { continue }
5493|            $group = @($recs | Where-Object { $_.Group -eq $r.Group })
