358|    $top = Get-GitOutput -Root $Cwd -GitArgs @('rev-parse', '--show-toplevel')
359|    if ($top) {
360|        $first = ([string]@($top)[0]).Trim()
361|        if ($first -and (Test-Path -LiteralPath $first)) {
362|            return (Resolve-Path -LiteralPath $first).Path
363|        }
364|    }
365|    # Not a git repository: fall back to the current directory.
366|    return $Cwd
