5335|# ----------------------------------------------------------------------------- availability view (wave 24)
5336|#
5337|# One truth about availability (D14-D17): the roster walk, codex-providers.ps1's rows, its -Short
5338|# line and the SessionStart hook judge a roster entry with the SAME verdict - the engine's launch
5339|# invariant, then Get-PreflightVerdict -RosterWalk (through Select-PanelMembers -All, which judges
5340|# EVERY entry, a weighty one too) - on the endpoint health of the ledgers of the repository the
5341|# command runs in (Read-AllTaskConsults). An entry is available, out (unavailable: missing
5342|# credentials, a recorded auth failure, a usage limit - with a known reset, or without one for 60
5343|# minutes -, an identity error, a launch refusal) or not checked (unknown: an engine sign-in that
5344|# -NoNetwork did not check, an unresolved identity, a check that could not run).
5345|
5346|# "in 2d 10h" | "in 3h 20m" | "in 52m" | "in <1m" - rounded to the hour from one day on, else to
5347|# the minute; "now" when the span is not positive.
5348|function Format-RelativeHint {
5349|    param([TimeSpan]$Span)
5350|    if ($Span.TotalSeconds -le 0) { return 'now' }
5351|    $m = [long][Math]::Round($Span.TotalMinutes, [MidpointRounding]::AwayFromZero)
5352|    if ($m -lt 1) { return 'in <1m' }
5353|    if ($m -ge 1440) {
5354|        $h = [long][Math]::Round($Span.TotalHours, [MidpointRounding]::AwayFromZero)
5355|        $d = [long][Math]::Floor($h / 24)
5356|        $hh = $h - 24 * $d
5357|        if ($hh -eq 0) { return "in ${d}d" }
5358|        return "in ${d}d ${hh}h"
5359|    }
5360|    if ($m -ge 60) {
5361|        $h = [long][Math]::Floor($m / 60)
5362|        $mm = $m - 60 * $h
5363|        if ($mm -eq 0) { return "in ${h}h" }
5364|        return "in ${h}h ${mm}m"
5365|    }
5366|    return "in ${m}m"
5367|}
